import React, { useState, useEffect, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import { QrReader } from 'react-qr-reader';
import './AttendanceScanner.css';

// Mock employee data with profile images
const VALID_EMPLOYEES = [
  { id: 'E001', name: 'John Smith', department: 'IT', image: '👨‍💼' },
  { id: 'E002', name: 'Sarah Johnson', department: 'HR', image: '👩‍💼' },
  { id: 'E003', name: 'Mike Davis', department: 'PM', image: '👨‍💻' },
  { id: 'E004', name: 'Emily Brown', department: 'Design', image: '👩‍🎨' },
  { id: 'E005', name: 'Robert Wilson', department: 'Business', image: '👨‍💼' },
  { id: 'E006', name: 'Lisa Anderson', department: 'IT', image: '👩‍💻' },
  { id: 'E007', name: 'James Martinez', department: 'Finance', image: '👨‍💼' },
  { id: 'E008', name: 'Jennifer Taylor', department: 'Marketing', image: '👩‍💼' },
];

const AttendanceScanner = ({ user, onLogout }) => {
  const [scanStatus, setScanStatus] = useState('idle'); // idle, success, error
  const [message, setMessage] = useState('');
  const [cameraError, setCameraError] = useState('');
  const [cameraReady, setCameraReady] = useState(false);
  const [qrReaderKey, setQrReaderKey] = useState(0);
  const [showManualEntry, setShowManualEntry] = useState(false);
  const [manualEmpId, setManualEmpId] = useState('');
  const [manualPassword, setManualPassword] = useState('');
  const [manualErrors, setManualErrors] = useState({});
  const [qrFrameClass, setQrFrameClass] = useState('active');
  const [lastScannedEmployee, setLastScannedEmployee] = useState(null);
  const isMountedRef = useRef(true);
  const navigate = useNavigate();

  // Request camera permissions on component mount
  useEffect(() => {
    isMountedRef.current = true;

    // Suppress all non-critical console warnings
    const originalWarn = console.warn;
    const originalError = console.error;
    
    console.warn = function(...args) {
      const message = String(args[0]);
      // Filter out all these known non-critical warnings
      if (message.includes('React Router') ||
          message.includes('Future Flag') ||
          message.includes('v7_startTransition') ||
          message.includes('v7_relativeSplatPath') ||
          message.includes('BrowserCodeReader') || 
          message.includes('Canvas2D') ||
          message.includes('willReadFrequently') ||
          message.includes('Trying to play video') ||
          message.includes('interrupted by a new load') ||
          message.includes('defaultProps will be removed') ||
          message.includes('It was not possible to play the video') ||
          message.includes('Support for defaultProps') ||
          message.includes('getImageData') ||
          message.includes('HTMLCanvasElementLuminanceSource') ||
          message.includes('Multiple readback operations')) {
        return;
      }
      originalWarn(...args);
    };

    console.error = function(...args) {
      const message = String(args[0]);
      if (message.includes('BrowserCodeReader') || 
          message.includes('Canvas2D') ||
          message.includes('willReadFrequently') ||
          message.includes('React Router') ||
          message.includes('defaultProps') ||
          message.includes('Support for defaultProps') ||
          message.includes('getImageData') ||
          message.includes('HTMLCanvasElementLuminanceSource') ||
          message.includes('Multiple readback operations')) {
        return;
      }
      originalError(...args);
    };

    const requestCameraPermission = async () => {
      try {
        const constraints = {
          video: { 
            facingMode: 'environment',
            width: { ideal: 1280 },
            height: { ideal: 720 }
          },
          audio: false 
        };
        
        const stream = await navigator.mediaDevices.getUserMedia(constraints);
        // Close the stream immediately, we just wanted to check permissions
        stream.getTracks().forEach(track => track.stop());
        if (isMountedRef.current) {
          setCameraReady(true);
          setCameraError('');
        }
      } catch (error) {
        if (isMountedRef.current) {
          setCameraReady(false);
          if (error.name === 'NotAllowedError') {
            setCameraError('Camera access denied. Please grant camera permissions in your browser settings.');
          } else if (error.name === 'NotFoundError') {
            setCameraError('No camera device found. Please connect a camera or check if it is already in use.');
          } else if (error.name === 'NotReadableError') {
            setCameraError('Camera is already in use by another application. Please close other apps using the camera.');
          } else {
            setCameraError(`Camera error: ${error.message || 'Unable to access camera'}`);
          }
        }
      }
    };

    requestCameraPermission();

    return () => {
      isMountedRef.current = false;
      // Restore original console functions
      console.warn = originalWarn;
      console.error = originalError;
    };
  }, []);

  // Reset QR reader key when camera ready state changes
  useEffect(() => {
    if (cameraReady) {
      setQrReaderKey(prev => prev + 1);
    }
  }, [cameraReady]);

  // Simulate QR Scanner for demo (if camera is not available)
  const handleSimulateScan = (employeeId) => {
    validateScan(employeeId);
  };

  const validateManualEntry = () => {
    const errors = {};
    if (!manualEmpId.trim()) {
      errors.empId = 'Employee ID is required';
    }
    if (!manualPassword.trim()) {
      errors.password = 'Password is required';
    }
    setManualErrors(errors);
    return Object.keys(errors).length === 0;
  };

  const handleManualSubmit = () => {
    if (!validateManualEntry()) {
      return;
    }
    // Process manual entry
    const employee = VALID_EMPLOYEES.find(emp => emp.id === manualEmpId);
    if (employee) {
      validateScan(manualEmpId);
      setShowManualEntry(false);
      setManualEmpId('');
      setManualPassword('');
      setManualErrors({});
    } else {
      setManualErrors({ empId: 'Employee not found' });
    }
  };

  const handleRetry = () => {
    setScanStatus('idle');
    setMessage('');
    setQrFrameClass('active');
  };

  const validateScan = (scannedId) => {
    const now = new Date();
    const timestamp = now.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
    const today = now.toISOString().split('T')[0];
    
    // Store scan attempt for audit trail
    const logScanAttempt = (status, reason, employeeData = null) => {
      const scanLog = JSON.parse(localStorage.getItem('scan_audit_log') || '[]');
      scanLog.push({
        timestamp: now.toISOString(),
        scannedId,
        status, // 'accepted' or 'rejected'
        reason,
        employeeData,
        scanner: user?.employeeName || 'Unknown'
      });
      // Keep only last 100 scans
      if (scanLog.length > 100) scanLog.shift();
      localStorage.setItem('scan_audit_log', JSON.stringify(scanLog));
    };

    // 1. Validate QR Code Format (must start with 'E' followed by 3 digits)
    const qrPattern = /^E\d{3}$/;
    if (!qrPattern.test(scannedId)) {
      setScanStatus('error');
      setMessage(`❌ Invalid QR Code Format: ${scannedId}`);
      setQrFrameClass('');
      logScanAttempt('rejected', 'Invalid QR code format');
      return;
    }

    // 2. Validate Employee Exists in Active Records
    const employee = VALID_EMPLOYEES.find(emp => emp.id === scannedId);
    
    if (!employee) {
      setScanStatus('error');
      setMessage(`❌ Employee Not Found: ${scannedId} is not in active records.`);
      setQrFrameClass('');
      logScanAttempt('rejected', 'Employee ID not found in system');
      return;
    }

    // 3. Check for Duplicate Scan (prevent scanning same QR within 5 seconds)
    const lastScanKey = 'last_scan_data';
    const lastScan = JSON.parse(localStorage.getItem(lastScanKey) || '{}');
    const timeSinceLastScan = now.getTime() - (lastScan.timestamp || 0);
    
    if (lastScan.employeeId === scannedId && timeSinceLastScan < 5000) {
      setScanStatus('error');
      setMessage(`⚠️ Duplicate Scan Detected: Please wait ${Math.ceil((5000 - timeSinceLastScan) / 1000)}s before scanning again.`);
      setQrFrameClass('');
      logScanAttempt('rejected', 'Duplicate scan within 5 seconds', employee);
      return;
    }

    // 4. Check Attendance Record for Today
    const storageKey = `attendance_${employee.id}_${today}`;
    const record = JSON.parse(localStorage.getItem(storageKey) || '{}');
    
    let action = '';
    let validationError = null;

    if (!record.timeIn) {
      // First scan of the day -> TIME IN
      action = 'IN';
      record.timeIn = timestamp;
      record.date = today;
      record.status = 'Present';
      record.employeeId = employee.id;
      record.employeeName = employee.name;
      record.department = employee.department;
    } else if (record.timeIn && !record.timeOut) {
      // Has TIME IN, now TIME OUT
      action = 'OUT';
      record.timeOut = timestamp;
      
      // Calculate duration
      const timeInDate = new Date(`${today} ${record.timeIn}`);
      const duration = Math.floor((now - timeInDate) / 1000 / 60); // minutes
      record.duration = duration;
    } else if (record.timeIn && record.timeOut) {
      // Already completed attendance for today
      validationError = `⚠️ ${employee.name} has already completed attendance for today.\nTime In: ${record.timeIn} | Time Out: ${record.timeOut}`;
    }

    // 5. Handle Validation Error
    if (validationError) {
      setScanStatus('error');
      setMessage(validationError);
      setQrFrameClass('');
      logScanAttempt('rejected', 'Already completed attendance for today', employee);
      return;
    }

    // 6. Save Attendance Record
    localStorage.setItem(storageKey, JSON.stringify(record));

    // 7. Update Last Scan Tracker (prevent duplicates)
    localStorage.setItem(lastScanKey, JSON.stringify({
      employeeId: employee.id,
      timestamp: now.getTime()
    }));

    // 8. Log Successful Scan
    logScanAttempt('accepted', `Check ${action} successful`, employee);

    // 9. Update UI State
    setScanStatus('success');
    setQrFrameClass('success');
    setLastScannedEmployee(employee);
    setMessage(`✅ Check ${action} Successful!\n${employee.name} (${employee.id})\n${timestamp}`);

    // 10. Redirect to employee dashboard after 2.5 seconds
    setTimeout(() => {
      navigate('/employee');
    }, 2500);
  };

  return (
    <div className="scanner-page">
      {/* Simplified Header/Navbar */}
      <div className="scanner-navbar">
        <div className="scanner-logo">
          <span>⚡ Gracewell NEXUS</span>
        </div>
        <div className="scanner-user">
          <span>{user?.employeeName || 'User'}</span>
          <div className="user-avatar">
            {user?.employeeName ? user.employeeName.charAt(0) : 'U'}
          </div>
          <button onClick={onLogout} style={{background: 'none', border: 'none', color: 'white', cursor: 'pointer'}}>Logout</button>
        </div>
      </div>

      <div className="scanner-left-panel">
        <h1>Gracewell NEXUS</h1>
        <h2>Attendance Checker</h2>
      </div>

      <div className="scanner-right-panel">
        <button className="manual-entry-btn" onClick={() => setShowManualEntry(true)}>
          <span>📝</span> Manual Entry
        </button>
        <div className="scanner-container">
          <div className={`qr-frame ${qrFrameClass}`}>
            <div className="qr-frame-corners-2"></div>
            <div className="scanner-camera-wrapper">
              {cameraReady ? (
                <QrReader
                  key={qrReaderKey}
                  onResult={(result) => {
                    if (result?.text && scanStatus === 'idle') {
                      validateScan(result.text);
                    }
                  }}
                  constraints={{ 
                    video: { 
                      facingMode: 'environment',
                      width: { ideal: 1280 },
                      height: { ideal: 720 }
                    }
                  }}
                  scanDelay={300}
                  videoContainerStyle={{ 
                    width: '100%', 
                    height: '100%',
                    position: 'absolute',
                    top: 0,
                    left: 0
                  }}
                  videoStyle={{
                    width: '100%',
                    height: '100%',
                    objectFit: 'cover'
                  }}
                />
              ) : (
                <div style={{ 
                  display: 'flex', 
                  alignItems: 'center', 
                  justifyContent: 'center', 
                  height: '100%',
                  background: '#f5f5f5',
                  borderRadius: '8px',
                  padding: '20px'
                }}>
                  <div style={{ textAlign: 'center', color: '#666' }}>
                    <p style={{ fontSize: '48px', marginBottom: '10px' }}>📷</p>
                    <p style={{ fontSize: '16px', marginBottom: '10px', fontWeight: '600' }}>Camera Not Available</p>
                    <p style={{ fontSize: '12px', color: '#999' }}>Please allow camera access in your browser settings</p>
                  </div>
                </div>
              )}
            </div>
          </div>

          <div className="scan-instruction">
            {cameraError ? (
              <div style={{ color: '#d32f2f', backgroundColor: '#ffebee', padding: '12px', borderRadius: '4px', marginBottom: '15px' }}>
                <strong>⚠️ Camera Error:</strong><br/>
                {cameraError}
              </div>
            ) : (
              <p>Please place your QR code front of the camera to begin the scan</p>
            )}
          </div>

          {message && (
            <div className={`scan-status ${scanStatus === 'success' ? 'status-success' : 'status-error'}`}>
              {scanStatus === 'success' && lastScannedEmployee && (
                <div style={{ display: 'flex', alignItems: 'center', gap: '15px' }}>
                  <div style={{ fontSize: '60px' }}>{lastScannedEmployee.image}</div>
                  <div style={{ textAlign: 'left' }}>
                    <div style={{ fontWeight: '600', fontSize: '16px' }}>{lastScannedEmployee.name}</div>
                    <div style={{ fontSize: '13px', opacity: 0.9 }}>ID: {lastScannedEmployee.id}</div>
                    <div style={{ fontSize: '13px', opacity: 0.9 }}>{lastScannedEmployee.department}</div>
                    <div style={{ fontSize: '12px', marginTop: '5px', color: '#27ae60', fontWeight: '500' }}>✓ Image Verified</div>
                  </div>
                </div>
              )}
              {scanStatus !== 'success' && message}
              {scanStatus === 'error' && (
                <button className="btn-retry" onClick={handleRetry} style={{ marginLeft: '10px' }}>
                  🔄 Retry
                </button>
              )}
            </div>
          )}
        </div>

        {/* Manual Entry Modal */}
        {showManualEntry && (
          <div className="scanner-overlay">
            <div className="scanner-modal">
              <h3>Manual Attendance Entry</h3>
              <p className="scanner-modal-description">
                Enter Employee ID and Password to confirm the changes
              </p>
              
              <div className="form-group">
                <label>Employee ID</label>
                <input 
                  type="text" 
                  value={manualEmpId}
                  onChange={(e) => {
                    setManualEmpId(e.target.value);
                    if (manualErrors.empId) {
                      setManualErrors({ ...manualErrors, empId: '' });
                    }
                  }}
                  className={manualErrors.empId ? 'error' : ''}
                  placeholder="Enter Employee ID"
                />
                {manualErrors.empId && <span className="error-message">{manualErrors.empId}</span>}
              </div>

              <div className="form-group">
                <label>Password</label>
                <input 
                  type="password" 
                  value={manualPassword}
                  onChange={(e) => {
                    setManualPassword(e.target.value);
                    if (manualErrors.password) {
                      setManualErrors({ ...manualErrors, password: '' });
                    }
                  }}
                  className={manualErrors.password ? 'error' : ''}
                  placeholder="Enter Password"
                />
                {manualErrors.password && <span className="error-message">{manualErrors.password}</span>}
              </div>

              <div className="scanner-modal-buttons">
                <button className="btn-cancel" onClick={() => {
                  setShowManualEntry(false);
                  setManualEmpId('');
                  setManualPassword('');
                  setManualErrors({});
                }}>
                  Cancel
                </button>
                <button className="btn-confirm" onClick={handleManualSubmit}>
                  Confirm
                </button>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default AttendanceScanner;
